import Link from 'next/link';
export default function LegacyRestockRequestPage(){return <div className="mx-auto max-w-2xl p-8"><div className="rounded-2xl border border-line bg-white p-8 shadow-soft"><h1 className="text-2xl font-black">Restock requests have been retired</h1><p className="mt-3 text-sm leading-6 text-gray-600">NearNow now uses the first-party Purchase Order workflow. Low stock is detected centrally, a Purchase Order is created when the configured reorder threshold is breached, and the vendor accepts, rejects, and dispatches that Purchase Order.</p><p className="mt-3 text-sm leading-6 text-gray-600">This legacy page is intentionally kept so old bookmarks do not break; it no longer calls the removed <code>/vendor/restock-requests</code> endpoint.</p><Link href="/vendor/orders" className="mt-6 inline-flex rounded-xl bg-ink px-4 py-2.5 text-sm font-semibold text-white">Open vendor workspace</Link></div></div>}
